- [ ] **Step 1: Write `src/tasks/TaskListScreen.tsx`**

```tsx
// tablet/src/tasks/TaskListScreen.tsx
import { useEffect, useState } from 'react'
import { getTasks, completeTask } from '../api/tasks'
import type { Task } from '../api/types'
import { enqueue, getQueue } from '../offline/queueStore'

export function TaskListScreen() {
  const [tasks, setTasks] = useState<Task[]>([])
  const [pendingIds, setPendingIds] = useState<Set<string>>(new Set())
  const [error, setError] = useState<string | null>(null)

  async function refresh() {
    try {
      setTasks(await getTasks())
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load tasks')
    }
    const queue = await getQueue()
    // Discriminated-union narrowing only works inside the ternary's true
    // branch, not through .filter() with a plain boolean predicate -- this
    // shape avoids an awkward `is Extract<...>` type predicate.
    const pendingTaskIds = queue
      .map((a) => (a.type === 'complete_task' ? a.payload.taskId : null))
      .filter((id): id is string => id !== null)
    setPendingIds(new Set(pendingTaskIds))
  }

  useEffect(() => {
    refresh()
  }, [])

  async function handleComplete(task: Task) {
    setError(null)
    try {
      const updated = await completeTask(task.id)
      setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)))
    } catch {
      await enqueue({
        id: crypto.randomUUID(),
        type: 'complete_task',
        queuedAt: new Date().toISOString(),
        payload: { taskId: task.id },
      })
      setPendingIds((prev) => new Set(prev).add(task.id))
    }
  }

  return (
    <div className="p-8">
      <h2 className="text-xl font-semibold text-gray-900 mb-4">Tasks</h2>
      <ul className="space-y-2">
        {tasks.map((task) => (
          <li
            key={task.id}
            className="flex items-center justify-between bg-white p-3 rounded border border-gray-200"
          >
            <div>
              <p className="text-gray-900">{task.title}</p>
              <p className="text-xs text-gray-500">
                {task.priority} · {task.status}
                {task.due_date ? ` · due ${task.due_date}` : ''}
              </p>
            </div>
            {task.status === 'OPEN' && (
              <button
                onClick={() => handleComplete(task)}
                disabled={pendingIds.has(task.id)}
                className="px-3 py-1 rounded text-white bg-green-600 disabled:opacity-50 text-sm"
              >
                {pendingIds.has(task.id) ? 'Syncing…' : 'Complete'}
              </button>
            )}
          </li>
        ))}
        {tasks.length === 0 && <p className="text-sm text-gray-500">No tasks assigned.</p>}
      </ul>
      {error && <p className="mt-4 text-sm text-red-600">{error}</p>}
    </div>
  )
}
```

(A task queued as completing keeps showing its real `OPEN` status with a disabled "Syncing…" button rather than optimistically flipping to `COMPLETED` client-side — safer: if the queued completion later comes back permanently-failed [409, e.g. a manager already cancelled it], nothing needs to be un-done in the UI, because nothing was ever shown as done.)

- [ ] **Step 2: Write `src/goals/GoalProgressScreen.tsx`**

```tsx
// tablet/src/goals/GoalProgressScreen.tsx
import { useEffect, useState } from 'react'
import { getGoals, getGoalProgress } from '../api/goals'
import type { GoalProgress } from '../api/types'

export function GoalProgressScreen() {
  const [progress, setProgress] = useState<GoalProgress[]>([])
  const [error, setError] = useState<string | null>(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    async function load() {
      try {
        const goals = await getGoals()
        setProgress(await Promise.all(goals.map((g) => getGoalProgress(g.id))))
      } catch {
        setError('Failed to load goals -- check your connection.')
      }
      setLoading(false)
    }
    load()
  }, [])

  if (loading) return <div className="p-8 text-gray-500">Loading…</div>

  return (
    <div className="p-8">
      <h2 className="text-xl font-semibold text-gray-900 mb-4">Goals</h2>
      <ul className="space-y-2">
        {progress.map((p) => (
          <li key={p.goal_id} className="bg-white p-3 rounded border border-gray-200">
            <p className="text-gray-900">{p.metric_type}</p>
            <p className="text-sm text-gray-600">
              {p.achieved} / {p.target}
            </p>
          </li>
        ))}
        {progress.length === 0 && !error && <p className="text-sm text-gray-500">No goals assigned.</p>}
      </ul>
      {error && <p className="mt-4 text-sm text-red-600">{error}</p>}
    </div>
  )
}
```

- [ ] **Step 3: Write `src/Layout.tsx`**

Mirrors `dashboard/src/Layout.tsx` (read it first) — same nav-bar shape, tablet's own routes, and this is where `useSyncQueue()` is mounted (only renders once the rep is authenticated, since it's always used inside `ProtectedRoute`):

```tsx
// tablet/src/Layout.tsx
import { NavLink, Outlet } from 'react-router-dom'
import { useAuth } from './auth/AuthContext'
import { useSyncQueue } from './offline/useSyncQueue'

function navLinkClass({ isActive }: { isActive: boolean }): string {
  return isActive ? 'text-blue-600 font-medium text-sm' : 'text-gray-600 hover:text-gray-900 text-sm'
}

export function Layout() {
  const { user, logout } = useAuth()
  useSyncQueue()

  return (
    <div className="min-h-screen bg-gray-50">
      <nav className="bg-white border-b border-gray-200 px-6 py-3 flex items-center justify-between">
        <div className="flex items-center gap-4">
          <span className="font-semibold text-gray-900">Atlas Field Force</span>
          <NavLink to="/" end className={navLinkClass}>Tracking</NavLink>
          <NavLink to="/visit" className={navLinkClass}>Visit</NavLink>
          <NavLink to="/tasks" className={navLinkClass}>Tasks</NavLink>
          <NavLink to="/goals" className={navLinkClass}>Goals</NavLink>
        </div>
        <div className="flex items-center gap-4">
          <span className="text-sm text-gray-500">{user?.email}</span>
          <button onClick={logout} className="text-sm text-gray-600 hover:text-gray-900">
            Sign out
          </button>
        </div>
      </nav>
      <main>
        <Outlet />
      </main>
    </div>
  )
}
```

