import { apiFetch } from './client'
import type { Goal, GoalProgress } from './types'

export function getGoals(limit = 50, offset = 0): Promise<Goal[]> {
  return apiFetch<Goal[]>(`/api/v1/goals?limit=${limit}&offset=${offset}`)
}

export function getGoalProgress(goalId: string): Promise<GoalProgress> {
  return apiFetch<GoalProgress>(`/api/v1/goals/${goalId}/progress`)
}

export function logGoalValue(goalId: string, value: number): Promise<Goal> {
  return apiFetch<Goal>(`/api/v1/goals/${goalId}/log-value`, {
    method: 'POST',
    body: JSON.stringify({ value }),
  })
}

// Hand-written mirrors of the backend's Pydantic response schemas
// (backend/app/{pings,visits,tasks,goals}/schemas.py), trimmed to the
// rep-scoped fields this app actually needs -- no admin-only fields.

export type { AuthUser } from '../auth/AuthContext'

// Matches PingOut (backend/app/pings/schemas.py)
export interface Ping {
  id: string
  recorded_at: string
  latitude: number
  longitude: number
  accuracy: number | null
}

// Matches VisitOut (backend/app/visits/schemas.py)
export interface Visit {
  id: string
  rep_id: string
  zone_id: string | null
  checked_in_at: string
  checked_out_at: string | null
  latitude: number
  longitude: number
  geofence_verified: boolean
  notes: string | null
  external_reference: string | null
}

// Matches TaskOut (backend/app/tasks/schemas.py)
export interface Task {
  id: string
  assigned_to: string
  title: string
  due_date: string | null
  status: string
  priority: string
  external_reference: string | null
  created_at: string
  completed_at: string | null
}

// Matches GoalOut (backend/app/goals/schemas.py)
export interface Goal {
  id: string
  rep_id: string
  metric_type: string
  target: number
  period_start: string
  period_end: string
  manual_value: number | null
  created_at: string
}

// Matches GoalProgress (backend/app/goals/schemas.py)
export interface GoalProgress {
  goal_id: string
  rep_id: string
  metric_type: string
  target: number
  achieved: number
  period_start: string
  period_end: string
}
